    "web.channels.settings.connectionHelp.matrix": "API는 봇 액세스 토큰으로 Matrix /sync를 폴링하므로 공개 URL이나 콜백 구성이 필요하지 않습니다. 암호화된 방은 지원되지 않으며 암호화된 이벤트는 삭제됩니다.",
    "web.channels.settings.connectionHelp.discord": "API는 Discord Gateway 연결을 유지하므로 공개 URL이나 콜백 구성이 필요하지 않습니다. Developer Portal의 Bot → Privileged Gateway Intents에서 MESSAGE_CONTENT를 활성화하세요.",
    "web.channels.settings.connectionHelp.weixin": "API는 봇 토큰으로 Tencent iLink 봇 게이트웨이를 롱 폴링하므로 공개 URL이 필요하지 않습니다. 개인 WeChat은 다이렉트 메시지만 지원하며 그룹 채팅은 전달되지 않습니다. 세션이 만료되면(errcode -14) QR 코드를 다시 스캔하고 토큰을 업데이트하세요.",
    "web.channels.settings.webhookHelp.telegram": "자격 증명을 저장하면 Telegram 웹훅이 자동으로 등록됩니다 — 붙여넣을 필요가 없습니다.",
