    "web.channels.settings.webhookHelp.github": "GitHub 앱 만들기 흐름이 앱에 이 웹훅 URL을 자동으로 설정합니다. 직접 만든 앱이라면 issues 및 issue_comment 이벤트와 함께 앱 웹훅 URL로 설정하세요.",
