    "web.channels.settings.webhookHelp.line": "자격 증명을 저장하면 LINE 웹훅 URL이 자동으로 설정됩니다 — 붙여 넣을 것이 없습니다. LINE Developers 콘솔의 Messaging API에서 \"Use webhook\"을 켜고, 봇이 두 번 답하지 않도록 자동 응답 메시지를 끄세요.",
