    "web.channels.settings.setupMode.lark": "Lark 설정 모드",
    "web.channels.settings.setupMode.weixin": "WeChat 설정 모드",
    "web.channels.settings.help.telegramCreate": "@BotFather를 통해 봇을 만들고 토큰을 붙여넣으세요. 웹훅 등록은 대신 처리합니다.",
    "web.channels.settings.help.telegramEdit": "허용된 사용자 또는 그룹 채팅을 비워 두면 누구나 사용할 수 있습니다. 운영자는 /model 같은 에이전트 전체 명령을 실행할 수 있으며, 운영자가 없으면 Telegram에서 해당 명령이 비활성화됩니다.",
    "web.channels.settings.help.slackCreate": "저장한 후 채널 인바운드 URL을 Slack 앱의 Event Subscriptions에 붙여넣으세요. 허용된 사용자를 비워 두면 워크스페이스의 누구나 봇을 사용할 수 있습니다. 운영자는 /model 같은 에이전트 전체 명령을 실행할 수 있으며, 운영자가 없으면 Slack에서 /model이 비활성화됩니다.",
    "web.channels.settings.help.slackEdit": "허용된 사용자를 비워 두면 워크스페이스의 누구나 봇을 사용할 수 있습니다. 운영자는 /model 같은 에이전트 전체 명령을 실행할 수 있으며, 운영자가 없으면 Slack에서 /model이 비활성화됩니다.",
    "web.channels.settings.help.linearCreate": "Linear 워크스페이스에서 애플리케이션을 만들고 Agent session 이벤트가 있는 웹훅을 활성화한 다음 저장 후 채널 인바운드 URL을 붙여넣으세요. 클라이언트 자격 증명이 Manyfold의 앱 토큰 발급을 허용합니다. 직접 발급한 경우 액세스 토큰을 대신 입력하세요. 허용된 사용자를 비워 두면 워크스페이스의 누구나 에이전트를 멘션할 수 있습니다.",
    "web.channels.settings.help.githubCreate": "먼저 채널을 만든 다음 페이지에서 “GitHub 앱 만들기”를 사용하세요 — GitHub가 앱 자격 증명을 자동으로 돌려줍니다. 이슈에서 앱을 멘션해 작업을 시작하세요. 저장소를 비워 두면 앱이 설치된 모든 저장소에 답변합니다.",
    "web.channels.settings.help.discordCreate": "Discord는 Gateway WebSocket을 사용하므로 공개 URL이 필요하지 않습니다. Developer Portal의 Bot → Privileged Gateway Intents에서 MESSAGE_CONTENT 인텐트를 활성화하세요. 그렇지 않으면 봇이 메시지 텍스트를 볼 수 없습니다.",
    "web.channels.settings.help.matrixCreate": "Matrix는 /sync 롱 폴링을 사용하므로 웹훅 URL이 필요하지 않습니다. 암호화된 방은 지원되지 않으며 암호화된 이벤트는 삭제됩니다.",
    "web.channels.settings.help.weixinCreate": "Tencent iLink 봇 게이트웨이를 통한 개인 WeChat은 다이렉트 메시지만 지원하며 웹훅 URL이 필요하지 않습니다. 운영자 ID를 비워 두면 에이전트 전체 명령이 비활성화됩니다.",
    "web.channels.settings.help.larkManual": "허용된 사용자를 비워 두면 누구나 봇에 접근할 수 있습니다. 운영자는 /model 같은 에이전트 전체 명령을 실행할 수 있으며, 운영자가 없으면 Feishu/Lark에서 /model이 비활성화됩니다.",
    "web.channels.settings.help.weixinEdit": "개인 WeChat은 다이렉트 메시지만 지원합니다. 운영자 ID를 비워 두면 에이전트 전체 명령이 비활성화됩니다(예: /model).",
    "web.channels.settings.help.whatsappEdit": "WhatsApp은 WhatsApp Web을 통해 연결되므로 이 채널에는 webhook URL이 필요하지 않습니다. 허용 발신자나 그룹 채팅을 비워 두면 제한하지 않습니다. 운영자는 /model 같은 에이전트 전체 명령을 실행할 수 있으며, 운영자가 없으면 해당 명령은 WhatsApp에서 비활성화됩니다. 발신자는 전화번호 또는 jid로 입력할 수 있습니다.",
    "web.channels.settings.help.linearEdit": "에이전트가 작업하는 동안 활동에는 Linear 세션의 생각, 도구 호출, 계획이 표시되고 최종 결과만 결과를 게시합니다. 자격 증명을 교체하면 모두 한 번에 바뀌므로 변경할 때 서명 시크릿을 다시 입력하세요.",
    "web.channels.settings.help.githubEdit": "허용된 로그인이 비어 있으면 연결 관계 게이트로 대체됩니다(기본값은 저장소 소유자, 조직 구성원, 공동 작업자). NONE을 추가하면 누구에게나 열 수 있습니다. 위임 레이블을 이슈에 추가하면 멘션 없이 작업이 시작됩니다. 운영자 로그인을 비워 두면 에이전트 전체 명령이 비활성화됩니다(예: /model).",
    "web.channels.settings.help.lineCreate": "LINE Developers 콘솔에서 Messaging API 채널을 만들고 장기 채널 액세스 토큰을 발급한 뒤 두 값을 여기에 붙여 넣으세요. 웹훅 URL은 저희가 설정하지만 \"Use webhook\"은 콘솔에서 직접 켜야 합니다. 답변은 실시간 미리보기 없는 일반 텍스트이며, 각 답변은 LINE 요금제의 메시지 한도에서 차감됩니다.",
    "web.channels.settings.help.lineEdit": "허용 사용자나 그룹 ID를 비워 두면 누구나 사용할 수 있습니다. 운영자는 /model 같은 에이전트 전역 명령을 실행할 수 있으며, 운영자가 없으면 해당 명령은 LINE에서 비활성화됩니다. 자격 증명 교체는 둘을 한 번에 바꾸므로 채널 시크릿과 액세스 토큰을 함께 다시 입력하세요.",
    "web.channels.settings.errors.larkWebhookCredentials": "Lark/Feishu 웹훅 채널에는 Verification Token 또는 Encrypt Key가 필요합니다.",
    "web.channels.settings.errors.linearCredentials": "Linear에는 액세스 토큰 또는 클라이언트 ID와 클라이언트 시크릿이 모두 필요합니다.",
    "web.channels.settings.errors.matrixHomeserver": "Matrix 홈서버 URL이 필요합니다.",
    "web.channels.settings.errors.matrixAccessToken": "Matrix 액세스 토큰이 필요합니다.",
