    "web.channels.settings.errors.linearRotation": "Linear 자격 증명을 교체하려면 웹훅 서명 시크릿과 액세스 토큰 또는 클라이언트 ID 및 클라이언트 시크릿이 모두 필요합니다.",
    "web.channels.settings.errors.githubRotation": "GitHub 자격 증명을 교체하려면 앱 ID, 개인 키, 웹훅 시크릿이 모두 필요합니다.",
