    "web.agentNew.frameworkDescriptions.dify": "외부 — /chat-messages SSE를 통해 Dify 앱을 연결합니다. 파일시스템 워크스페이스가 없으며 공급자는 설정 → 외부 에이전트에서 관리합니다.",
